fn on_event(ctx) {
    if ctx.event.kind == "player_kill" {
        chat.send(`Local kills this update: ${ctx.event.count}`);
        debug(log, `Cumulative kills: ${ctx.event.total}`);
    }
}

fn on_event(ctx) {
    if ctx.event.kind != "round_ended" || ctx.current_match == () { return; }
    let rounds = ctx.current_match.last_rounds(1);
    if rounds.len == 0 { return; }
    let r = rounds[0];
    if r.player.kills == () || r.player.kills < 5 { return; }
    let key = ctx.event.session_id + ":" + r.index;
    if storage.get("last_ace", "") == key { return; }
    storage.set("last_ace", key);
    chat.send("Ace! A secret-case draw starts in two minutes.");
    scheduler.after("ace_giveaway", Duration::from_mins(2), #{alias: "secret_case"});
}

fn on_timer(ctx) {
    if ctx.timer.key != "ace_giveaway" { return; }
    let filter = UserFilter::create().min_messages(3).min_characters(15)
        .reward_redemptions(RewardFilter::create().reward("entry_reward")
            .statuses(["COMPLETED"]).min_count(1).during(Duration::from_days(7)));
    let viewers = chat.recent_chatters(Duration::from_mins(5), filter);
    let winner = random.pick(viewers);
    if winner == () {
        log.info("No eligible chatters; no reward triggered.");
        return;
    }
    let result = rewards.trigger(ctx.timer.payload.alias, winner.id);
    if result.ok {
        chat.send(`@${winner.login} won the secret case! Check your necko7 inventory.`);
    } else {
        let code = if result.contains("code") { result.code } else { "unknown_result" };
        log.warn(`Secret-case outcome: ${code}; inspect Scripts Logs and inventory before retrying.`);
        // One deliberate, neutral announcement; no per-error spam or automatic retrigger.
        chat.send("The draw finished, but the reward needs review. Check the channel inventory.");
    }
}

fn on_event(ctx) {
    if ctx.event.kind == "match_started" {
        rewards.enable_for("round_drop", Duration::from_mins(2));
        log.info("Reward visibility window requested.");
    }
}

fn on_event(ctx) {
    if ctx.event.kind == "match_started" && !scheduler.exists("hide_drop") {
        rewards.set_visible("round_drop", true);
        scheduler.after("hide_drop", Duration::from_mins(2), #{alias: "round_drop"});
    }
}
fn on_timer(ctx) {
    if ctx.timer.key == "hide_drop" {
        rewards.set_visible(ctx.timer.payload.alias, false);
    }
}

fn on_event(ctx) {
    if ctx.event.kind == "player_kill" {
        let total = storage.increment("observed_kills", ctx.event.count);
        log.info(`Project has observed ${total} kills.`);
    }
}

fn on_event(ctx) {
    if ctx.event.kind != "match_started" { return; }
    let filter = UserFilter::create().min_messages(5).min_characters(100);
    let candidates = users.recent_chatters(Duration::from_mins(5), filter);
    let winner = random.pick(candidates);
    if winner == () { log.info("Nobody meets the activity criteria."); return; }
    let activity = users.user_stats(winner.id, Duration::from_mins(5));
    log.info(`Picked ${winner.login}: ${activity.messages} messages.`);
}

fn on_event(ctx) {
    if ctx.event.kind != "match_started" { return; }
    let reward_filter = RewardFilter::create().reward("entry_reward")
        .statuses(["COMPLETED"]).min_count(2).during(Duration::from_days(7));
    let filter = UserFilter::create().min_messages(1).reward_redemptions(reward_filter);
    let viewers = chat.recent_chatters(Duration::from_mins(5), filter);
    log.info(`Eligible returning viewers: ${viewers.len}`);
}

fn on_timer(ctx) {
    let result = rewards.trigger("secret_case", ctx.timer.payload.user_id);
    if result.ok {
        log.info("Fulfillment admitted; inspect inventory for delivery.");
    } else {
        let code = if result.contains("code") { result.code } else { "unknown_result" };
        log.warn(`Trigger needs review: ${code}`);
        if result.contains("fulfillment_id") { log.info(result.fulfillment_id); }
    }
}

fn on_event(ctx) {
    if ctx.event.kind != "round_ended" || ctx.current_match == () { return; }
    let recent = ctx.current_match.last_rounds(3);
    if recent.len != 3 { return; }
    let expected = recent[0].index;
    for r in recent {
        if r.index == () || r.index != expected { return; }
        if r.player.side == () || r.winner == () || r.player.side != r.winner { return; }
        expected += 1;
    }
    log.info("Three consecutive observed local-side wins.");
}

import "events/kills" as kills;
import "timers/reminder" as reminder;
fn on_event(ctx) { kills::handle(ctx); }
fn on_timer(ctx) { reminder::handle(ctx); }

